"""Real running engine; isolated technical worlds, never fabricated voyage outcomes."""
import json
from pathlib import Path
from test_visual45_integration import VisualIntegration
class DroneIntegration(VisualIntegration):
 def setup_drone(self,p):
  self.configure(p,"s.frontier.enabled=false;s.navigation.hold=true;s.remoteCore.autonomyEnabled=true;const q=s.crew[0];q.room=q.target='C04';q.route=[];q.nav=null;q.taskMinutes=0;q.energy=95;")
 def until(self,p,predicate,limit=1000):
  for i in range(limit):
   self.advance(p,1);s=p.evaluate('''()=>{const s=__icarusSoak.snapshot(),o=s.droneOperations;return {tick:s.tick,droneOperations:{...o,archive:[],drones:Object.fromEntries(Object.entries(o.drones).map(([id,d])=>[id,{...d,clips:[],ring:[]}]))}};}''')
   if predicate(s):return self.snap(p)
  self.fail('Condition not reached: '+json.dumps(s.get('droneOperations'))[:3000]+' crew '+str(p.evaluate('__icarusSoak.snapshot().crew.filter(p=>p.job==="Engineer").map(p=>({name:p.name,room:p.room,target:p.target,task:p.task,assignment:p.droneAssignment,energy:p.energy,emergency:p.emergencyId,expedition:p.expeditionId}))')))
 def test_drone_autonomous_physical_survey_return_reload_and_actual_captured_frames(self):
  p=self.page();before=self.snap(p);self.setup_drone(p);s=self.until(p,lambda s:bool(s['droneOperations']['history']));o=s['droneOperations'];self.assertGreater(len(o['known']),1);self.assertTrue(o['archive']);self.assertGreaterEqual(o['drones']['DRONE-1']['charged'],90);self.assertTrue(any(f.get('image','').startswith('data:image/png;base64,') for c in o['archive'] for f in c['frames']));self.assertEqual(s['droneAudit'],[]);self.assertEqual(s['resourceAudit'],[]);self.assertTrue(s['unifiedWorld']['organisms']['XENO-INITIAL']['dormant']);self.assertEqual(s['unifiedWorld']['military']['doors']['23'],'sealed');self.assertEqual([c['name'] for c in s['crew']],[c['name'] for c in before['crew']]);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
 def test_drone_mid_segment_save_catchup_and_persistent_fog(self):
  p=self.page();self.setup_drone(p);s=self.until(p,lambda s:any(d.get('edge') and d['edge']['elapsed']>=1 for d in s['droneOperations']['drones'].values()));p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s);self.advance(p,120);after=self.snap(p);self.assertGreater(after['tick'],s['tick']);self.assertEqual(after['droneAudit'],[]);self.assertEqual(after['resourceAudit'],[]);self.assertTrue(set(s['droneOperations']['known']).issubset(after['droneOperations']['known']))
 def test_drone_observation_ui_uses_real_camera_and_received_map(self):
  p=self.page();self.setup_drone(p);s=self.until(p,lambda s:any(d['stage']=='field' and d['node']==1 for d in s['droneOperations']['drones'].values()));self.deck(p,'missions','active');p.locator('.drone-ops').scroll_into_view_if_needed();self.assertIn('sectors received',p.locator('.drone-status').inner_text());self.assertEqual(p.locator('.drone-map button').count(),25);self.assertGreater(p.locator('.drone-map button:disabled').count(),0);self.operations(p);p.locator('#camera-scene').scroll_into_view_if_needed();p.wait_for_function('ICARUSObservationLive.camera.tick===__icarusSoak.time()');p.locator('.obs-select').select_option('DRONE-1');p.evaluate('ICARUSObservationLive.camera.draw(true)');room=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="DRONE-1")');self.assertTrue(room['available']);self.assertEqual(room['location'],1);self.assertEqual(room['actors'],[]);p.wait_for_function('''()=>{const c=document.createElement('canvas');ICARUSPixelCamera.draw(c,__icarusSoak.observation().rooms.find(r=>r.id==='DRONE-1'),{paused:true,reduced:true});return c.toDataURL()===document.getElementById('observation-primary').toDataURL();}''');out=Path(__file__).parent/'reports/phase46/screenshots';out.mkdir(parents=True,exist_ok=True);p.locator('#observation-primary').screenshot(path=str(out/'actual_drone_camera.png'));p.screenshot(path=str(out/'bridge_drone_camera.png'));self.deck(p,'missions','active');p.locator('.drone-ops').scroll_into_view_if_needed();p.screenshot(path=str(out/'exploration_interface.png'));(out/'capture_source.json').write_text(json.dumps({'scope':'Actual renderer in isolated technical test world; not spontaneous user voyage or physical recorded video','tick':s['tick'],'room':room,'drone':s['droneOperations']['drones']['DRONE-1']},indent=2))
 def test_drone_receiver_outage_withholds_findings_and_clips_then_ingests(self):
  p=self.page();self.setup_drone(p);s=self.until(p,lambda s:any(d['stage']=='outbound' for d in s['droneOperations']['drones'].values()));self.change(p,"s.shipSystems.zones.science.circuitIsolated=true;");before=len(self.snap(p)['droneOperations']['archive']);self.advance(p,90);s=self.snap(p);self.assertEqual(len(s['droneOperations']['archive']),before);self.assertTrue(any(d['clips'] for d in s['droneOperations']['drones'].values()));self.assertTrue(all(not r['available'] for r in p.evaluate('__icarusSoak.observation().rooms.filter(r=>r.id.startsWith("DRONE-"))')));self.change(p,"s.shipSystems.zones.science.circuitIsolated=false;");self.advance(p,100);s=self.snap(p);self.assertGreater(len(s['droneOperations']['archive']),before);self.assertEqual(s['resourceAudit'],[])
 def test_drone_management_controls_are_optional_and_no_unknown_target(self):
  p=self.page();self.setup_drone(p);self.deck(p,'missions','active');p.locator('.drone-auto').click();self.assertFalse(self.snap(p)['droneOperations']['enabled']);p.wait_for_function('document.querySelector(".drone-status").textContent.includes("held")');p.locator('.drone-build').click();self.assertTrue(self.snap(p)['droneOperations']['buildRequested']);self.until(p,lambda s:bool(s['droneOperations']['drones']));self.until(p,lambda s:s['droneOperations']['drones']['DRONE-1']['battery']>=90);self.deck(p,'missions','active');p.locator('.drone-launch').click();self.assertIn(self.snap(p)['droneOperations']['drones']['DRONE-1']['stage'],['outbound','field'],p.locator('.drone-feedback').inner_text()+' / '+str(self.snap(p)['droneOperations']['drones']['DRONE-1']));p.locator('.drone-recall').click();self.assertTrue(self.snap(p)['droneOperations']['drones']['DRONE-1']['pendingRecall']);self.advance(p,1);self.assertTrue(self.snap(p)['droneOperations']['drones']['DRONE-1']['mission']['returning']);self.assertEqual(s:=self.snap(p)['droneAudit'],[])
 def test_drone_real_clock_catchup_and_monday_boundary_do_not_reset_active_navigation(self):
  p=self.page();self.setup_drone(p);s=self.until(p,lambda s:any(d.get('edge') for d in s['droneOperations']['drones'].values()));before=s['tick'];known=set(s['droneOperations']['known']);p.evaluate("__icarusSoak.realStart(Date.parse('2026-11-08T23:59:00Z'),'UTC')");r=p.evaluate("__icarusSoak.realAdvance(Date.parse('2026-11-09T00:01:00Z'),60)");after=self.snap(p);self.assertEqual(after['tick']-before,8);self.assertGreater(after['episode'],s['episode']);self.assertTrue(known.issubset(after['droneOperations']['known']));self.assertEqual(after['droneAudit'],[]);again=p.evaluate("__icarusSoak.realAdvance(Date.parse('2026-11-09T00:01:00Z'),60)");self.assertEqual(again['ticks'],0);self.assertEqual(self.snap(p),after)
 def test_drone_rendering_and_management_view_do_not_advance_or_reveal_local_state(self):
  p=self.page();self.setup_drone(p);s=self.until(p,lambda s:any(d['stage']=='field' for d in s['droneOperations']['drones'].values()));self.deck(p,'missions','active');before=self.snap(p);p.locator('.drone-map button:not(:disabled)').first.click();p.locator('.drone-ops details').nth(1).locator('summary').click();p.locator('.drone-camera').select_option('DRONE-1');p.wait_for_timeout(1100);self.assertEqual(self.snap(p),before);self.assertNotIn('military cargo canister',p.locator('.drone-map').inner_text());self.assertTrue(p.locator('.drone-map button:disabled').count()>0)
